#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding, int dilation,
    int Hout, int Wout,
    int numOcTiles,
    int IH_TILE, int IW_TILE)
{
  constexpr int TILE_OH    = 16;
  constexpr int TILE_OW    = 16;
  constexpr int OcPerBlock = 16;
  const int tx = threadIdx.x;
  const int ty = threadIdx.y;
  const int tid = ty * TILE_OW + tx;
  const int nthreads = TILE_OH * TILE_OW;
  const int oc_tile = blockIdx.z % numOcTiles;
  const int n       = blockIdx.z / numOcTiles;
  const int oc_base = oc_tile * OcPerBlock;
  const int ow_base = blockIdx.x * TILE_OW;
  const int oh_base = blockIdx.y * TILE_OH;
  const int ow = ow_base + tx;
  const int oh = oh_base + ty;
  const bool valid_out = (oh < Hout) && (ow < Wout);
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  // Weight tensor: (Cout, Cin, K, K)
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, K, K),
      make_stride((int64_t)Cin * K * K, (int64_t)K * K, K, Int<1>{})
  );
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  T* sX_ptr0 = sW_ptr + (size_t)OcPerBlock * (size_t)Cin * (size_t)K * (size_t)K;
  T* sX_ptr1 = sX_ptr0 + (size_t)IH_TILE * (size_t)IW_TILE;
  // Shared weight tensor for this Oc tile: (OcPerBlock, Cin, K, K)
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, Cin, K, K),
      make_stride(Cin * K * K, K * K, K, Int<1>{})
  );
  // Double-buffered shared input tiles (with halo) to allow pipelined
  // loading of the next input channel's tile while computing on the
  // current one.
  auto sX0 = make_tensor(
      make_smem_ptr(sX_ptr0),
      make_shape(IH_TILE, IW_TILE),
      make_stride(IW_TILE, Int<1>{})
  );
  auto sX1 = make_tensor(
      make_smem_ptr(sX_ptr1),
      make_shape(IH_TILE, IW_TILE),
      make_stride(IW_TILE, Int<1>{})
  );
  // Cooperatively load weights for this Oc tile into shared memory
  int total_w = OcPerBlock * Cin * K * K;
  for (int idx = tid; idx < total_w; idx += nthreads) {
    int rem = idx;
    int kw = rem % K; rem /= K;
    int kh = rem % K; rem /= K;
    int ic = rem % Cin; rem /= Cin;
    int occ = rem; // 0..OcPerBlock-1
    int oc = oc_base + occ;
    T wval = T(0);
    if (oc < Cout) {
      wval = mW(oc, ic, kh, kw);
    }
    sW(occ, ic, kh, kw) = wval;
  }
  float acc[OcPerBlock];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    acc[occ] = bval;
  }
  const int ih0 = oh_base * stride - padding;
  const int iw0 = ow_base * stride - padding;
  const int total_x = IH_TILE * IW_TILE;
  // Helper to load an input-channel tile (with halo) into a shared buffer
  auto load_x_tile = [&](int ic, auto& dst) {
    for (int idx = tid; idx < total_x; idx += nthreads) {
      int lh = idx / IW_TILE;
      int lw = idx - lh * IW_TILE;
      int ih = ih0 + lh;
      int iw = iw0 + lw;
      T val = T(0);
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        val = mX(ic, ih, iw);
      }
      dst(lh, lw) = val;
    }
  };
  __syncthreads();
  // Prefetch the first input channel's tile before entering the main loop
  if (Cin > 0) {
    load_x_tile(0, sX0);
  }
  __syncthreads();
  // Main convolution loop: reduce over input channels, staging each
  // channel's spatial patch (with halo) into shared memory for reuse
  // across the whole output tile and all OcPerBlock output channels.
  // Double-buffered so that loading the next channel's tile overlaps
  // with computation on the current channel's tile, hiding global
  // memory latency behind the FMA-heavy inner loop.
  for (int ic = 0; ic < Cin; ++ic) {
    const bool curbuf0 = ((ic & 1) == 0);
    if (ic + 1 < Cin) {
      if (curbuf0) {
        load_x_tile(ic + 1, sX1);
      } else {
        load_x_tile(ic + 1, sX0);
      }
    }
    if (valid_out) {
      #pragma unroll
      for (int kh = 0; kh < K; ++kh) {
        int lh = ty * stride + kh * dilation;
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
          int lw = tx * stride + kw * dilation;
          float xval = curbuf0 ? (float)sX0(lh, lw) : (float)sX1(lh, lw);
          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            float wval = (float)sW(occ, ic, kh, kw);
            acc[occ] += xval * wval;
          }
        }
      }
    }
    __syncthreads();
  }
  // Write results back
  if (valid_out) {
    #pragma unroll
    for (int occ = 0; occ < OcPerBlock; ++occ) {
      int oc = oc_base + occ;
      if (oc >= Cout) continue;
      mY(oc, oh, ow) = static_cast<T>(acc[occ]);
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");
  TORCH_CHECK(groups == 1, "Only groups=1 is supported by this kernel");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1)");
  TORCH_CHECK(w.size(2) == w.size(3), "kernel must be square");
  int64_t K = w.size(2);
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int TILE_OH    = 16;
  constexpr int TILE_OW    = 16;
  constexpr int OcPerBlock = 16;
  const int numWTiles  = (int)((Wout + TILE_OW - 1) / TILE_OW);
  const int numHTiles  = (int)((Hout + TILE_OH - 1) / TILE_OH);
  const int numOcTiles = (int)((Cout + OcPerBlock - 1) / OcPerBlock);
  const int IH_TILE = (TILE_OH - 1) * stride + (int)(K - 1) * dilation + 1;
  const int IW_TILE = (TILE_OW - 1) * stride + (int)(K - 1) * dilation + 1;
  dim3 block(TILE_OW, TILE_OH);
  dim3 grid(
      (unsigned)numWTiles,
      (unsigned)numHTiles,
      (unsigned)(N * (int64_t)numOcTiles)
  );
  size_t smem_bytes = (size_t)OcPerBlock * (size_t)Cin * (size_t)K * (size_t)K * sizeof(float)
                     + 2 * (size_t)IH_TILE * (size_t)IW_TILE * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }
  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)K, stride, padding, dilation,
      (int)Hout, (int)Wout,
      numOcTiles,
      IH_TILE, IW_TILE
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""
conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    Standard 2D convolution (square kernel, asymmetric spatial input),
    implemented with a single custom CUDA kernel using CuTe tensors.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert groups == 1, "Only groups=1 is supported by this custom kernel"
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        C_in = self.in_channels
        C_out = self.out_channels
        K = self.kernel_size
        self.weight = nn.Parameter(torch.empty(C_out, C_in, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(C_out))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()
        self._ext = conv2d_ext
    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size * self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

